 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  const n = a.length;
  const m = b.length;

  // Intern lines as integers so the inner loops compare numbers.
  const ids = new Map();
  const idA = new Int32Array(n);
  const idB = new Int32Array(m);
  for (let i = 0; i < n; i++) {
    let id = ids.get(a[i]);
    if (id === undefined) {
      id = ids.size;
      ids.set(a[i], id);
    }
    idA[i] = id;
  }
  const inB = new Uint8Array(ids.size);
  for (let j = 0; j < m; j++) {
    let id = ids.get(b[j]);
    if (id === undefined) {
      id = ids.size;
      ids.set(b[j], id);
    } else {
      inB[id] = 1;
    }
    idB[j] = id;
  }
  const inA = ids.size; // ids below this value occur in a

  // Lines absent from the other side can never be matched; dropping them keeps
  // the LCS length unchanged and shrinks the Myers search space.
  const keepA = [];
  for (let i = 0; i < n; i++) if (inB[idA[i]]) keepA.push(i);
  const keepB = [];
  for (let j = 0; j < m; j++) if (idB[j] < inA && idB[j] < inB.length) keepB.push(j);

  const fa = new Int32Array(keepA.length);
  for (let i = 0; i < keepA.length; i++) fa[i] = idA[keepA[i]];
  const fb = new Int32Array(keepB.length);
  for (let j = 0; j < keepB.length; j++) fb[j] = idB[keepB[j]];

  const matchedA = new Uint8Array(n);
  const matchedB = new Uint8Array(m);
  const fMatchedA = new Uint8Array(fa.length);
  const fMatchedB = new Uint8Array(fb.length);
  myersMatch(fa, fb, fMatchedA, fMatchedB);
  for (let i = 0; i < fa.length; i++) if (fMatchedA[i]) matchedA[keepA[i]] = 1;
  for (let j = 0; j < fb.length; j++) if (fMatchedB[j]) matchedB[keepB[j]] = 1;

  // The k-th matched line of a pairs with the k-th matched line of b. Between
  // matches, emit every delete before every insert.
  const script = [];
  let i = 0;
  let j = 0;
  while (i < n || j < m) {
    while (i < n && !matchedA[i]) script.push({ op: 'delete', line: a[i++] });
    while (j < m && !matchedB[j]) script.push({ op: 'insert', line: b[j++] });
    if (i < n && j < m) {
      script.push({ op: 'equal', line: a[i] });
      i++;
      j++;
