'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  const n = a.length;
  const m = b.length;

  // Intern lines as integers so the inner loops compare numbers.
  const ids = new Map();
  const idA = new Int32Array(n);
  const idB = new Int32Array(m);
  for (let i = 0; i < n; i++) {
    let id = ids.get(a[i]);
    if (id === undefined) {
      id = ids.size;
      ids.set(a[i], id);
    }
    idA[i] = id;
  }
  const inB = new Uint8Array(ids.size);
  for (let j = 0; j < m; j++) {
    let id = ids.get(b[j]);
    if (id === undefined) {
      id = ids.size;
      ids.set(b[j], id);
    } else {
      inB[id] = 1;
    }
    idB[j] = id;
  }
  const inA = ids.size; // ids below this value occur in a

  // Lines absent from the other side can never be matched; dropping them keeps
  // the LCS length unchanged and shrinks the Myers search space.
  const keepA = [];
  for (let i = 0; i < n; i++) if (inB[idA[i]]) keepA.push(i);
  const keepB = [];
  for (let j = 0; j < m; j++) if (idB[j] < inA && idB[j] < inB.length) keepB.push(j);

  const fa = new Int32Array(keepA.length);
  for (let i = 0; i < keepA.length; i++) fa[i] = idA[keepA[i]];
  const fb = new Int32Array(keepB.length);
  for (let j = 0; j < keepB.length; j++) fb[j] = idB[keepB[j]];

  const matchedA = new Uint8Array(n);
  const matchedB = new Uint8Array(m);
  const fMatchedA = new Uint8Array(fa.length);
  const fMatchedB = new Uint8Array(fb.length);
  myersMatch(fa, fb, fMatchedA, fMatchedB);
  for (let i = 0; i < fa.length; i++) if (fMatchedA[i]) matchedA[keepA[i]] = 1;
  for (let j = 0; j < fb.length; j++) if (fMatchedB[j]) matchedB[keepB[j]] = 1;

  // The k-th matched line of a pairs with the k-th matched line of b. Between
  // matches, emit every delete before every insert.
  const script = [];
  let i = 0;
  let j = 0;
  while (i < n || j < m) {
    while (i < n && !matchedA[i]) script.push({ op: 'delete', line: a[i++] });
    while (j < m && !matchedB[j]) script.push({ op: 'insert', line: b[j++] });
    if (i < n && j < m) {
      script.push({ op: 'equal', line: a[i] });
      i++;
      j++;
    }
  }
  return script;
}

/**
 * Mark a longest common subsequence of integer arrays A and B in matchedA and
 * matchedB using Myers' linear-space divide-and-conquer (middle snake).
 */
function myersMatch(A, B, matchedA, matchedB) {
  const total = A.length + B.length;
  const maxD = Math.ceil(total / 2);
  const vLength = 2 * maxD + 2;
  const v1 = new Int32Array(vLength);
  const v2 = new Int32Array(vLength);

  // Explicit work stack of [a0, a1, b0, b1] ranges; order is irrelevant since
  // results are recorded as flags.
  const stack = [0, A.length, 0, B.length];
  while (stack.length > 0) {
    let b1 = stack.pop();
    let b0 = stack.pop();
    let a1 = stack.pop();
    let a0 = stack.pop();

    while (a0 < a1 && b0 < b1 && A[a0] === B[b0]) {
      matchedA[a0++] = 1;
      matchedB[b0++] = 1;
    }
    while (a0 < a1 && b0 < b1 && A[a1 - 1] === B[b1 - 1]) {
      matchedA[--a1] = 1;
      matchedB[--b1] = 1;
    }
    if (a0 === a1 || b0 === b1) continue;

    const split = middleSnake(A, a0, a1, B, b0, b1, v1, v2);
    if (split === null) continue; // nothing in common
    const x = a0 + split[0];
    const y = b0 + split[1];
    stack.push(a0, x, b0, y, x, a1, y, b1);
  }
}

/**
 * Find a split point (x, y), relative to (a0, b0), lying on an optimal edit
 * path for A[a0..a1) vs B[b0..b1). Returns null when no line is shared.
 */
function middleSnake(A, a0, a1, B, b0, b1, v1, v2) {
  const n = a1 - a0;
  const m = b1 - b0;
  const maxD = Math.ceil((n + m) / 2);
  const vOffset = maxD;
  const vLength = 2 * maxD + 2;
  v1.fill(-1, 0, vLength);
  v2.fill(-1, 0, vLength);
  v1[vOffset + 1] = 0;
  v2[vOffset + 1] = 0;
  const delta = n - m;
  const front = (delta & 1) !== 0;
  let k1start = 0;
  let k1end = 0;
  let k2start = 0;
  let k2end = 0;

  for (let d = 0; d < maxD; d++) {
    for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
      const k1Offset = vOffset + k1;
      let x1;
      if (k1 === -d || (k1 !== d && v1[k1Offset - 1] < v1[k1Offset + 1])) {
